insert into public.ascend_questions (id, subject, level, domain, skill, passage, data_table, question, choices, answer_index, accept, explanation, status, source, published_at) values
('mathl3d_001', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If (x + 4)/3 − (x − 2)/5 = 4, what is the value of x?', null, null, '["17"]'::jsonb, 'Multiply by 15: 5(x + 4) − 3(x − 2) = 60, so 2x + 26 = 60 and x = 17.', 'published', 'import', now()),
('mathl3d_002', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'In the equation a(3x + 2) = 12x + 8, a is a constant. If the equation has infinitely many solutions, what is the value of a?', '["12", "4", "8", "3"]'::jsonb, 1, null, 'Expanding gives 3ax + 2a = 12x + 8. Both sides match for every x when 3a = 12 and 2a = 8, so a = 4.', 'published', 'import', now()),
('mathl3d_003', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If 3x/4 − 2 = x/6 + 5, what is the value of x?', '["12", "36", "6", "7"]'::jsonb, 0, null, 'Multiply by 12: 9x − 24 = 2x + 60, so 7x = 84 and x = 12.', 'published', 'import', now()),
('mathl3d_004', 'math', 3, 'Algebra', 'Linear functions', null, null, 'A linear function f satisfies f(−2) = 11 and f(4) = −7. For what value of x is f(x) = 0?', null, null, '["5/3", "1.666", "1.667"]'::jsonb, 'The slope is (−7 − 11) ÷ (4 − (−2)) = −3. Then 11 = −3(−2) + b gives b = 5, so f(x) = −3x + 5, which is 0 when x = 5/3.', 'published', 'import', now()),
('mathl3d_005', 'math', 3, 'Algebra', 'Linear functions', null, null, 'A plumber charges C = 65h + 90 dollars for a job lasting h hours. If the plumber raises the hourly rate by 20% and keeps the same fixed fee, how many more dollars will a 5-hour job cost?', '["65", "13", "18", "83"]'::jsonb, 0, null, 'The hourly rate rises by 0.20 × 65 = 13 dollars, so a 5-hour job costs 13 × 5 = 65 dollars more. The fixed fee doesn''t change.', 'published', 'import', now()),
('mathl3d_006', 'math', 3, 'Algebra', 'Linear functions', null, null, 'Line ℓ passes through (−3, 4) and is perpendicular to the line 2x − 5y = 7. What is the y-intercept of line ℓ?', null, null, '["-3.5", "−3.5", "-7/2", "−7/2"]'::jsonb, '2x − 5y = 7 has slope 2/5, so ℓ has slope −5/2. At x = 0: y = 4 − (5/2)(3) = 4 − 7.5 = −3.5.', 'published', 'import', now()),
('mathl3d_007', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, '3x + 2y = 7
5x − 4y = 41

If (x, y) is the solution to the system, what is the value of x − y?', null, null, '["9"]'::jsonb, 'Double the first equation: 6x + 4y = 14. Adding to the second gives 11x = 55, so x = 5 and y = (7 − 15)/2 = −4. Then x − y = 9.', 'published', 'import', now()),
('mathl3d_008', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'kx + 3y = 4
2x − 6y = 5

In the system, k is a constant. For what value of k does the system have no solution?', '["−1", "1", "2", "−2"]'::jsonb, 0, null, 'The second line has slope 1/3. The first has slope −k/3, so the lines are parallel when k = −1. Then −x + 3y = 4 doubles to 2x − 6y = −8, which differs from 5, so there is no solution.', 'published', 'import', now()),
('mathl3d_009', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'A chemist mixes a 20% saline solution with a 50% saline solution to make 60 liters of a 30% saline solution. How many liters of the 20% solution does she use?', '["36", "20", "30", "40"]'::jsonb, 3, null, 'a + b = 60 and 0.2a + 0.5b = 18. Substituting b = 60 − a: 30 − 0.3a = 18, so a = 40.', 'published', 'import', now()),
('mathl3d_010', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'The digits of a two-digit number add up to 11. When the digits are reversed, the new number is 27 greater than the original. What is the original number?', null, null, '["47"]'::jsonb, 'With tens digit t and units digit u: t + u = 11 and (10u + t) − (10t + u) = 27, so u − t = 3. Then u = 7, t = 4, and the number is 47.', 'published', 'import', now()),
('mathl3d_011', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'A delivery van can carry at most 1,800 pounds, including the driver. The driver weighs 180 pounds and each box weighs 45 pounds. What is the greatest number of boxes the van can carry?', '["35", "36", "40", "44"]'::jsonb, 1, null, '180 + 45b ≤ 1,800 gives 45b ≤ 1,620, so b ≤ 36.', 'published', 'import', now()),
('mathl3d_012', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'Which of the following describes all solutions to −2 < 5 − 3x ≤ 11?', '["−2 < x ≤ 7/3", "−7/3 < x ≤ 2", "−2 ≤ x < 7/3", "x < −2 or x ≥ 7/3"]'::jsonb, 2, null, 'Subtract 5: −7 < −3x ≤ 6. Dividing by −3 reverses both signs: 7/3 > x ≥ −2.', 'published', 'import', now()),
('mathl3d_013', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 1/(x − 3) − 1/(x + 3), for x ≠ 3 and x ≠ −3?', '["6/(x^{2} − 9)", "−6/(x^{2} − 9)", "2x/(x^{2} − 9)", "0"]'::jsonb, 0, null, 'Use the common denominator (x − 3)(x + 3) = x^{2} − 9: [(x + 3) − (x − 3)]/(x^{2} − 9) = 6/(x^{2} − 9).', 'published', 'import', now()),
('mathl3d_014', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'If x^{2} + y^{2} = 34 and xy = 15, what is the value of (x − y)^{2}?', null, null, '["4"]'::jsonb, '(x − y)^{2} = x^{2} + y^{2} − 2xy = 34 − 30 = 4.', 'published', 'import', now()),
('mathl3d_015', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'The expression (3x − 2)(ax + 5), where a is a constant, is equivalent to 12x^{2} + bx − 10. What is the value of b?', '["23", "7", "−7", "4"]'::jsonb, 1, null, '3a = 12, so a = 4. The x-terms are 15x − 2ax = 15x − 8x = 7x, so b = 7.', 'published', 'import', now()),
('mathl3d_016', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (16x^{8})^{3/4}, for x > 0?', '["8x^{11}", "12x^{6}", "8x^{6}", "4x^{6}"]'::jsonb, 2, null, '16^{3/4} = (16^{1/4})^{3} = 2^{3} = 8, and (x^{8})^{3/4} = x^{6}.', 'published', 'import', now()),
('mathl3d_017', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the sum of the solutions to 3x^{2} + 4x − 20 = 0?', '["−4/3", "−20/3", "4/3", "2"]'::jsonb, 0, null, 'Factor: (3x + 10)(x − 2) = 0, so x = −10/3 or 2. Their sum is −4/3.', 'published', 'import', now()),
('mathl3d_018', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the solution set of √(2x + 7) = x + 2?', '["{1}", "{3}", "{−3, 1}", "{−3}"]'::jsonb, 0, null, 'Squaring: 2x + 7 = x^{2} + 4x + 4, so x^{2} + 2x − 3 = 0 and x = 1 or −3. Check: x = −3 gives √1 = −1, which is false, so −3 is extraneous. Only x = 1 works.', 'published', 'import', now()),
('mathl3d_019', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'For what value of c does the equation x^{2} − 10x + c = 0 have exactly one real solution?', null, null, '["25"]'::jsonb, 'Exactly one solution means the discriminant is 0: 100 − 4c = 0, so c = 25.', 'published', 'import', now()),
('mathl3d_020', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'y = x^{2} − 4x + 1
y = 2x − 8

How many solutions does the system have?', '["Zero", "Exactly two", "Exactly one", "Infinitely many"]'::jsonb, 2, null, 'Setting them equal: x^{2} − 6x + 9 = 0, or (x − 3)^{2} = 0. The only solution is x = 3, so the line touches the parabola once.', 'published', 'import', now()),
('mathl3d_021', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'If 8^{x + 1} = 4^{2x}, what is the value of x?', '["3", "−3", "1", "3/7"]'::jsonb, 0, null, 'Write both sides as powers of 2: 2^{3x + 3} = 2^{4x}. Then 3x + 3 = 4x, so x = 3.', 'published', 'import', now()),
('mathl3d_022', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = a(x − 2)(x + 6), where a is a constant, and f(0) = 24. What is the maximum value of f?', '["−2", "32", "16", "24"]'::jsonb, 1, null, 'f(0) = a(−2)(6) = −12a = 24, so a = −2 and the parabola opens down. Its vertex is halfway between the zeros, at x = −2: f(−2) = −2(−4)(4) = 32.', 'published', 'import', now()),
('mathl3d_023', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'A bacteria population is modeled by P(t) = 500(2)^{t/3}, where t is the time in hours. How many hours does it take the population to grow from 500 to 8,000?', null, null, '["12"]'::jsonb, '8,000 ÷ 500 = 16 = 2^{4}, so t/3 = 4 and t = 12.', 'published', 'import', now()),
('mathl3d_024', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'Which function''s value decreases by 20% each time x increases by 1?', '["f(x) = 50(1.2)^{x}", "f(x) = 50(0.8)^{x}", "f(x) = 50(0.2)^{x}", "f(x) = 50 − 0.2x"]'::jsonb, 1, null, 'Decreasing by 20% leaves 80% each step, so the growth factor is 0.8.', 'published', 'import', now()),
('mathl3d_025', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The graph of f(x) = (x − 3)^{2} + 2 is shifted 4 units to the left and 5 units down to form the graph of g. What is the y-intercept of the graph of g?', '["(0, 4)", "(0, 6)", "(0, −12)", "(0, −2)"]'::jsonb, 3, null, 'g(x) = (x − 3 + 4)^{2} + 2 − 5 = (x + 1)^{2} − 3. Then g(0) = 1 − 3 = −2.', 'published', 'import', now()),
('mathl3d_026', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The functions g and h satisfy g(x) = 2x + 1 and h(g(x)) = 4x^{2} + 4x + 3 for all x. Which of the following defines h?', '["h(x) = 2x^{2} + 2", "h(x) = 4x^{2} + 2", "h(x) = x^{2} + 3", "h(x) = x^{2} + 2"]'::jsonb, 3, null, '(2x + 1)^{2} = 4x^{2} + 4x + 1, so h(g(x)) = (2x + 1)^{2} + 2. That means h(x) = x^{2} + 2.', 'published', 'import', now()),
('mathl3d_027', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'Pipe A can fill an empty tank in 9 hours. Pipe B can drain a full tank in 12 hours. If both pipes are opened when the tank is empty, how many hours will it take to fill the tank?', null, null, '["36"]'::jsonb, 'Each hour the tank gains 1/9 − 1/12 = 4/36 − 3/36 = 1/36 of its volume, so it fills in 36 hours.', 'published', 'import', now()),
('mathl3d_028', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A map has a scale of 1 : 250,000. Two towns are 6.4 centimeters apart on the map. What is the actual distance between them, in kilometers? (1 kilometer = 100,000 centimeters)', '["16", "160", "1.6", "39"]'::jsonb, 0, null, '6.4 × 250,000 = 1,600,000 cm, and 1,600,000 ÷ 100,000 = 16 km.', 'published', 'import', now()),
('mathl3d_029', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A metal block has a density of 7.8 grams per cubic centimeter. It is a rectangular prism measuring 5 cm by 4 cm by 2.5 cm. What is its mass, in grams?', '["6.4", "97.5", "390", "195"]'::jsonb, 2, null, 'Volume = 5 × 4 × 2.5 = 50 cubic cm. Mass = 7.8 × 50 = 390 grams.', 'published', 'import', now()),
('mathl3d_030', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A store raises the price of a lamp by 25%. By what percent must the new price be reduced to bring it back to the original price?', '["80%", "75%", "20%", "25%"]'::jsonb, 2, null, 'If the original price is 100, the new price is 125. Removing 25 from 125 is a 25/125 = 20% reduction.', 'published', 'import', now()),
('mathl3d_031', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'In 2020, a town had 8,000 residents, and 35% of them were under 18. In 2025, the town had 10,500 residents, and 32% of them were under 18. By what percent did the number of residents under 18 increase?', '["8.6%", "3%", "31.25%", "20%"]'::jsonb, 3, null, 'Under 18: 0.35 × 8,000 = 2,800 and 0.32 × 10,500 = 3,360. The increase is 560, and 560 ÷ 2,800 = 0.20 = 20%.', 'published', 'import', now()),
('mathl3d_032', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The mean of 8 numbers is 15. When one number is removed, the mean of the remaining 7 numbers is 14. What number was removed?', null, null, '["22"]'::jsonb, 'The total falls from 8 × 15 = 120 to 7 × 14 = 98, so the removed number is 22.', 'published', 'import', now()),
('mathl3d_033', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The data set 3, 7, 7, 9, 12, 16, x has a mean of 10. What is the value of x?', '["14", "16", "9", "10"]'::jsonb, 1, null, 'Seven values with mean 10 total 70. The known values total 54, so x = 16.', 'published', 'import', now()),
('mathl3d_034', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'A data set has a standard deviation of s. Which change to the data set will leave the standard deviation unchanged?', '["Adding a new value equal to the largest value", "Multiplying every value by 5", "Removing the largest value", "Adding 5 to every value"]'::jsonb, 3, null, 'Adding the same number to every value shifts the data without changing how spread out it is. The other changes alter the spread.', 'published', 'import', now()),
('mathl3d_035', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'A linear model for the price y, in dollars, of a used car that is x years old is y = 18,500 − 1,250x. A 6-year-old car sells for $12,000. What is the residual (actual minus predicted) for this car, in dollars?', '["11,000", "−1,000", "6,500", "1,000"]'::jsonb, 3, null, 'Predicted: 18,500 − 1,250(6) = 11,000. Residual: 12,000 − 11,000 = 1,000.', 'published', 'import', now()),
('mathl3d_036', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, '{"h": ["", "Passed", "Did not pass"], "r": [["Took prep course", "72", "18"], ["No prep course", "48", "62"]]}'::jsonb, 'The table summarizes the results of 200 students on a certification exam.

If a student who did not pass is chosen at random, what is the probability that the student took the prep course?', '["9/100", "9/40", "31/40", "1/5"]'::jsonb, 1, null, '18 + 62 = 80 students did not pass, and 18 of them took the prep course: 18/80 = 9/40.', 'published', 'import', now()),
('mathl3d_037', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'Two fair number cubes, each numbered 1 through 6, are rolled. What is the probability that the sum of the numbers is 8?', '["1/9", "1/6", "5/36", "7/36"]'::jsonb, 2, null, 'The pairs (2, 6), (3, 5), (4, 4), (5, 3), and (6, 2) give 8. That is 5 of 36 outcomes.', 'published', 'import', now()),
('mathl3d_038', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'In a random sample of 400 households in a town, 22% had a pet bird. The estimate has a margin of error of 4 percentage points. The town has 15,000 households. Which of the following is a plausible number of households in the town with a pet bird?', '["2,400", "4,200", "1,500", "3,500"]'::jsonb, 3, null, 'The plausible range is 18% to 26% of 15,000, or 2,700 to 3,900 households. Only 3,500 is in that range.', 'published', 'import', now()),
('mathl3d_039', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangle''s length is 3 more than twice its width, and its area is 65 square units. What is the perimeter of the rectangle?', null, null, '["36"]'::jsonb, 'w(2w + 3) = 65 gives 2w^{2} + 3w − 65 = 0, or (2w + 13)(w − 5) = 0, so w = 5 and the length is 13. Perimeter = 2(5 + 13) = 36.', 'published', 'import', now()),
('mathl3d_040', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A sphere of radius 3 fits exactly inside a cylinder with radius 3 and height 6. What is the volume of the space inside the cylinder that is not filled by the sphere?', '["72π", "18π", "36π", "54π"]'::jsonb, 1, null, 'Cylinder: π(3^{2})(6) = 54π. Sphere: (4/3)π(3^{3}) = 36π. The difference is 18π.', 'published', 'import', now()),
('mathl3d_041', 'math', 3, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'In triangle ABC, AB = AC, and the measure of angle A is 3 times the measure of angle B. What is the measure of angle A?', '["108°", "60°", "36°", "72°"]'::jsonb, 0, null, 'AB = AC makes angles B and C equal. Then 3B + B + B = 180, so B = 36 and A = 108.', 'published', 'import', now()),
('mathl3d_042', 'math', 3, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'In triangle PQR, point S lies on PQ and point T lies on PR so that segment ST is parallel to QR. If PS = 5, SQ = 3, and ST = 10, what is the length of QR?', null, null, '["16"]'::jsonb, 'Triangle PST is similar to triangle PQR, with PS/PQ = 5/8. So 10/QR = 5/8, and QR = 16.', 'published', 'import', now()),
('mathl3d_043', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In right triangle ABC, angle C is the right angle and sin A = 5/13. What is tan B?', '["13/5", "5/12", "12/5", "12/13"]'::jsonb, 2, null, 'The side opposite A is 5 and the hypotenuse is 13, so the other leg is 12. For angle B, the opposite side is 12 and the adjacent side is 5.', 'published', 'import', now()),
('mathl3d_044', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A ladder leans against a wall, making a 60° angle with the ground. The top of the ladder touches the wall 12√3 feet above the ground. How long is the ladder, in feet?', null, null, '["24"]'::jsonb, 'sin 60° = (12√3)/L, and sin 60° = √3/2. So L = 12√3 ÷ (√3/2) = 24.', 'published', 'import', now()),
('mathl3d_045', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle in the xy-plane has equation x^{2} + y^{2} − 8x + 6y = 11. What is the radius of the circle?', '["5", "36", "6", "√11"]'::jsonb, 2, null, 'Complete the squares: (x − 4)^{2} + (y + 3)^{2} = 11 + 16 + 9 = 36, so the radius is 6.', 'published', 'import', now()),
('mathl3d_046', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A chord of length 16 is 6 units from the center of a circle. What is the radius of the circle?', null, null, '["10"]'::jsonb, 'The perpendicular from the center bisects the chord, making a right triangle with legs 8 and 6. The radius is √(64 + 36) = 10.', 'published', 'import', now()),
('mathl3d_047', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'What is 135° in radians?', '["2π/3", "5π/6", "3π/2", "3π/4"]'::jsonb, 3, null, 'Multiply by π/180: 135π/180 = 3π/4.', 'published', 'import', now()),
('rwl3d_001', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Although the archive''s printed catalog appeared comprehensive, historians soon found it to be only ____: entire decades of correspondence had never been indexed.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["redundant", "impartial", "exhaustive", "partial"]'::jsonb, 3, null, 'A catalog missing whole decades of letters covers only part of the archive, so it is partial.', 'published', 'import', now()),
('rwl3d_002', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The economist''s 2010 forecast now seems remarkably ____: nearly every prediction she made about regional housing prices matched what actually happened over the following decade.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["derivative", "prescient", "ambiguous", "pessimistic"]'::jsonb, 1, null, 'Predictions that later came true show foresight, which is what prescient means.', 'published', 'import', now()),
('rwl3d_003', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Rather than ____ the senator''s argument outright, the columnist conceded its strongest points before raising several narrower objections.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["endorse", "reiterate", "dismiss", "summarize"]'::jsonb, 2, null, 'The columnist took the argument seriously instead of rejecting it, so the contrast calls for dismiss.', 'published', 'import', now()),
('rwl3d_004', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Composer Florence Price frequently ____ melodies from African American spirituals into her symphonies, weaving them into the large-scale structures of European classical music.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["isolated", "incorporated", "discarded", "withheld"]'::jsonb, 1, null, 'Price blended spiritual melodies into her symphonies, so she incorporated them.', 'published', 'import', now()),
('rwl3d_005', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The new findings do not ____ the earlier study so much as refine it: the study''s central conclusion still holds, though its estimates now have a narrower range.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["overturn", "replicate", "support", "publicize"]'::jsonb, 0, null, 'The core conclusion still holds, so the new findings refine the study rather than overturn it.', 'published', 'import', now()),
('rwl3d_006', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The naturalist''s careful, almost formal prose occasionally betrays her excitement, as when a sentence describing a rare orchid breaks off into a string of exclamations.', null, 'As used in the text, what does the word "betrays" most nearly mean?', '["abandons", "weakens", "reveals", "deceives"]'::jsonb, 2, null, 'Her excitement shows through the formal prose, so "betrays" means reveals.', 'published', 'import', now()),
('rwl3d_007', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Because the glacier''s retreat has been ____—slow for decades, then sudden during a few unusually warm summers—scientists caution against predicting its future from any single year''s measurements.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["steady", "reversible", "erratic", "negligible"]'::jsonb, 2, null, 'A retreat that is slow for decades and then sudden is irregular, or erratic.', 'published', 'import', now()),
('rwl3d_008', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The committee''s report was deliberately ____, laying out each option and its likely costs without recommending any, so that council members could reach their own conclusions.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["partisan", "dismissive", "neutral", "urgent"]'::jsonb, 2, null, 'A report that lists options without favoring any is neutral.', 'published', 'import', now()),
('rwl3d_009', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Although the board approved the new design, several members expressed reservations about its cost, warning that the budget might not cover unexpected repairs.', null, 'As used in the text, what does the word "reservations" most nearly mean?', '["doubts", "territories", "bookings", "savings"]'::jsonb, 0, null, 'Members warned about cost, so they had doubts.', 'published', 'import', now()),
('rwl3d_010', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Ynés Mexía did not begin studying botany until she was in her fifties. Over the next thirteen years, she traveled through Mexico, Peru, Brazil, and Alaska, often on horseback or by canoe, and collected well over 100,000 plant specimens. Hundreds of them turned out to be species unknown to science.', null, 'Which choice best states the main purpose of the text?', '["To explain how new plant species are named", "To highlight an achievement that is especially notable given when the person''s career began", "To compare the methods of several plant collectors", "To argue that botany should be taught to older adults"]'::jsonb, 1, null, 'The text stresses that Mexía started in her fifties and still collected an enormous number of specimens.', 'published', 'import', now()),
('rwl3d_011', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Tidal power has an advantage that wind and solar power lack: it is highly predictable. Because tides follow the motions of the Moon and Sun, engineers can forecast a tidal plant''s output years in advance. Few coastlines, however, have tides strong enough and bays shaped suitably enough to make such plants worth building.', null, 'Which choice best describes the function of the last sentence in the overall structure of the text?', '["It contradicts the claim that tides are predictable", "It gives a second advantage of tidal power", "It notes a limitation of the energy source that the earlier sentences praise", "It explains how tides are forecast"]'::jsonb, 2, null, 'After describing tidal power''s predictability, the text ends by pointing out that few places are suitable.', 'published', 'import', now()),
('rwl3d_012', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'The following text is from a short story.

Marisol rehearsed the apology the entire walk home, changing a word here and there, imagining her brother''s face going hard and silent. By the time she reached the porch, her hands were shaking. But when Tomás opened the door, he only laughed and held up their grandmother''s vase—glued, the crack nearly invisible—and asked what had taken her so long.', null, 'Which choice best describes the overall structure of the text?', '["It contrasts two characters'' opinions about a family heirloom", "It describes a character''s anxious anticipation and then a reaction that defies her expectations", "It describes a setting in detail and then introduces a conflict", "It explains how a vase is repaired"]'::jsonb, 1, null, 'Marisol dreads her brother''s anger, but he laughs and shows that he has already fixed the vase.', 'published', 'import', now()),
('rwl3d_013', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'On La Gomera, one of the Canary Islands, deep ravines separate many villages. Residents developed Silbo Gomero, a way of whistling Spanish that can be heard several kilometers away, far beyond the reach of a shout. Shepherds once used it to pass messages from slope to slope, and today it is taught in the island''s schools.', null, 'Which choice best states the main purpose of the text?', '["To explain why the island''s schools teach music", "To argue that whistled languages are more efficient than spoken ones", "To describe how a form of communication was adapted to a particular landscape", "To trace the history of the Spanish language"]'::jsonb, 2, null, 'The text explains that Silbo Gomero developed because whistles carry across the island''s deep ravines.', 'published', 'import', now()),
('rwl3d_014', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Renovating an old building is often more environmentally responsible than tearing it down and building a new one. Admittedly, older buildings can require costly upgrades to their insulation and wiring. Even so, reusing a building avoids the enormous energy cost of producing new concrete and steel, which can take decades of efficient operation to make up.', null, 'Which choice best describes the function of the second sentence in the overall structure of the text?', '["It provides the main evidence for the author''s claim", "It introduces a counterargument that the author accepts in full", "It acknowledges a drawback of the approach before the author reaffirms its value", "It describes the history of a particular building"]'::jsonb, 2, null, '"Admittedly" signals a concession; the third sentence then returns to the author''s claim with "Even so."', 'published', 'import', now()),
('rwl3d_015', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Around 1177 BCE, several powerful kingdoms of the eastern Mediterranean fell within a few decades. Some historians attribute this collapse chiefly to the Sea Peoples, groups of seafaring raiders whose attacks are described in Egyptian inscriptions.

Text 2
A growing number of scholars see the collapse as a systems failure. Prolonged drought, earthquakes, and the breakdown of long-distance trade weakened the kingdoms together. On this view, the migrations of the Sea Peoples were driven by the same crises, making the raiders as much a consequence of the collapse as a cause of it.', null, 'Based on the texts, how would the author of Text 2 most likely respond to the explanation in Text 1?', '["By arguing that the invasions were probably a symptom of broader problems rather than the main cause of the collapse", "By claiming that the eastern Mediterranean kingdoms never collapsed", "By suggesting that the invasions happened centuries later than Text 1 states", "By agreeing that the Sea Peoples alone caused the collapse"]'::jsonb, 0, null, 'Text 2 treats the invasions as one result of drought and trade breakdown, not the main cause.', 'published', 'import', now()),
('rwl3d_016', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
When insects chew on a willow''s leaves, the tree releases airborne chemicals. Nearby willows that detect these chemicals increase their own defenses. Some botanists describe this as plants communicating with one another.

Text 2
The evidence that undamaged plants respond to their neighbors'' chemical signals is strong. But communication implies a sender that benefits from being understood. A damaged plant gains little by alerting its rivals for sunlight. It is more accurate to say that nearby plants are eavesdropping on chemicals the damaged plant releases for its own reasons.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By claiming that the signals are produced only by insects", "By denying that plants release any chemicals when damaged", "By arguing that plants communicate in more complex ways than Text 1 suggests", "By accepting that plants react to chemical signals from damaged neighbors but objecting to calling this communication"]'::jsonb, 3, null, 'Text 2 accepts the chemical responses but prefers "eavesdropping," rejecting the idea that the damaged plant intends to warn anyone.', 'published', 'import', now()),
('rwl3d_017', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
A modern critic praises a 1930s novel set in rural Florida for its dialogue. By capturing the rhythms and humor of how the townspeople actually spoke, the critic argues, the author gave their everyday lives a dignity that most fiction of the period denied them.

Text 2
When the novel first appeared, some reviewers were disappointed. They believed that serious fiction about Black communities should focus on injustice, and they faulted the novel for concentrating instead on one woman''s personal search for love and independence.', null, 'Based on the texts, how would the reviewers described in Text 2 most likely respond to the critic in Text 1?', '["They would likely find the novel''s use of everyday speech less important than what they saw as a lack of social commentary", "They would claim that the novel was written in another language", "They would agree that the dialogue is the novel''s greatest strength", "They would argue that the novel contains no dialogue"]'::jsonb, 0, null, 'The early reviewers cared mainly about the novel''s message, so they would weigh the dialogue less heavily than the critic does.', 'published', 'import', now()),
('rwl3d_018', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'Maryam Mirzakhani, who in 2014 became the first woman to win the Fields Medal, studied the geometry of curved surfaces. She rarely relied on formulas alone. Instead, she sketched for hours on huge sheets of paper spread across the floor, drawing loops and shapes until patterns emerged. Her young daughter, watching, described her mother''s work as "painting."', null, 'Which choice best states the main idea of the text?', '["Mirzakhani preferred painting to mathematics", "Mirzakhani approached difficult mathematics in a highly visual, exploratory way", "Fields Medal winners usually work with computers", "Mirzakhani''s daughter became a mathematician"]'::jsonb, 1, null, 'The text focuses on her drawing-based method of exploring curved surfaces.', 'published', 'import', now()),
('rwl3d_019', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'The following text is from a short story.

My grandfather never told me why he checked every knot twice before we pushed the boat out. He simply did it, each morning, in the same order, while I watched. By the end of that summer, I noticed my own hands moving down the lines the same way, testing each knot before I''d even thought about it.', null, 'Based on the text, what is true about the narrator''s grandfather?', '["He prefers to fish alone", "He is impatient with the narrator''s questions", "He has recently learned how to fish", "He values preparation and teaches by example rather than by explanation"]'::jsonb, 3, null, 'He checks every knot without explaining why, and the narrator learns by copying him.', 'published', 'import', now()),
('rwl3d_020', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'The axolotl, a salamander native to lakes near Mexico City, can regrow a lost limb, damaged parts of its spinal cord, and even portions of its heart. Unlike humans, it heals these injuries without forming scar tissue. Researchers hope that understanding how the animal does this might one day help doctors improve healing in people.', null, 'According to the text, what makes the axolotl especially interesting to researchers?', '["It can survive outside water for months", "It can regrow complex body parts without forming scar tissue", "It lives longer than any other amphibian", "It changes color to match its surroundings"]'::jsonb, 1, null, 'The text says axolotls rebuild limbs, spinal cord, and heart tissue without scarring, which is why researchers study them.', 'published', 'import', now()),
('rwl3d_021', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'For decades, many economists assumed that shared resources such as pastures or fishing grounds would inevitably be overused unless they were either privatized or controlled by governments. Political economist Elinor Ostrom challenged this view. Studying forests, fisheries, and irrigation systems around the world, she documented communities that had managed shared resources sustainably for generations by developing their own rules and ways of enforcing them. Her work earned her the Nobel Prize in Economic Sciences in 2009.', null, 'Which choice best states the main idea of the text?', '["Ostrom argued that shared resources must always be sold to private owners", "Ostrom''s research showed that communities can successfully manage shared resources themselves", "Ostrom believed governments should control all forests and fisheries", "Ostrom studied only fishing villages in one country"]'::jsonb, 1, null, 'Her studies found communities managing forests, fisheries, and water through their own rules.', 'published', 'import', now()),
('rwl3d_022', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'A student is writing about recycling in a city. She notes that the amount of a material that residents put in recycling bins does not always reflect how much of it actually gets recycled. For example, ____', '{"h": ["Material", "Tons collected", "Recycling rate (%)"], "r": [["Paper", "4,200", "64"], ["Plastic", "1,100", "18"], ["Glass", "1,500", "31"], ["Aluminum", "600", "72"]]}'::jsonb, 'Which choice most effectively uses data from the table to complete the example?', '["paper made up the largest amount of material collected and had a 64% recycling rate", "plastic had a lower recycling rate than glass", "aluminum made up the smallest amount of material collected, yet it had the highest recycling rate, 72%", "more tons of glass than plastic were collected"]'::jsonb, 2, null, 'The claim is that tonnage doesn''t predict recycling success; aluminum had the least tonnage and the best rate.', 'published', 'import', now()),
('rwl3d_023', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'In a novel, the narrator has mixed feelings about the city where she lives, finding it both exhausting and irresistible.', null, 'Which quotation from the novel most effectively illustrates the claim?', '["\"I cursed its traffic and its prices every morning, and every evening I stood on the bridge and could not look away.\"", "\"My office was on the fourteenth floor of a gray building near the river.\"", "\"The city had eleven bridges, each painted a different color.\"", "\"I moved to the city in the spring of my twenty-third year.\""]'::jsonb, 0, null, 'Only this quotation shows both frustration and attachment, which is ambivalence.', 'published', 'import', now()),
('rwl3d_024', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'Gray squirrels in city parks approach people much more closely before fleeing than do gray squirrels in rural forests. Researchers hypothesize that this difference results from repeated exposure to people during a squirrel''s lifetime rather than from inherited differences between city and rural populations.', null, 'Which finding, if true, would most directly support the researchers'' hypothesis?', '["City squirrels are slightly larger than rural squirrels", "Rural squirrels have lived in the region for many more generations than city squirrels", "Squirrels moved from rural forests to a city park became as bold as the park''s original squirrels within a few months", "City squirrels and rural squirrels eat many of the same foods"]'::jsonb, 2, null, 'If rural squirrels quickly become bold in a city, the difference comes from experience, not inherited traits.', 'published', 'import', now()),
('rwl3d_025', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'Since an invasive mussel appeared in a northern lake in 2015, the number of young fish in the lake has dropped by nearly half. Because the mussels filter large amounts of plankton from the water, leaving less food for young fish, some biologists claim that the mussel is responsible for the decline.', null, 'Which finding, if true, would most directly weaken the biologists'' claim?', '["The mussel population in the lake has grown each year since 2015", "Fish populations declined by a similar amount over the same period in nearby lakes where the mussel has never been found", "Several fish species in the lake feed on plankton", "The mussels attach themselves to rocks and docks"]'::jsonb, 1, null, 'If lakes without the mussel saw the same decline, something other than the mussel likely caused it.', 'published', 'import', now()),
('rwl3d_026', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'An ecologist counted visits by three kinds of native bees to plots of native wildflowers and to plots of ornamental garden flowers. She concluded that native wildflowers attracted more visits from most, but not all, of the bee species studied.', '{"h": ["Bee", "Visits to native plots", "Visits to ornamental plots"], "r": [["Mining bee", "142", "37"], ["Sweat bee", "98", "61"], ["Bumblebee", "120", "133"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the ecologist''s conclusion?', '["Mining bees made 142 visits to native plots", "Bumblebees made more visits overall than sweat bees", "Mining bees and sweat bees visited native plots far more often than ornamental plots, but bumblebees made slightly more visits to ornamental plots", "All three species visited both kinds of plots"]'::jsonb, 2, null, 'The conclusion is "most but not all"; this choice shows two species favoring native plots and one that didn''t.', 'published', 'import', now()),
('rwl3d_027', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'In a speech about protecting a local river, a town council member argues that residents must act even though scientists are still uncertain about some of the river''s problems.', null, 'Which quotation from the speech most effectively illustrates the claim?', '["\"The river has flowed past this town for ten thousand years.\"", "\"We will never have every answer we want, and the river will not wait for us to find them.\"", "\"Our scientists have collected samples at fourteen sites.\"", "\"I first swam in this river when I was six years old.\""]'::jsonb, 1, null, 'This quotation admits uncertainty while urging action now.', 'published', 'import', now()),
('rwl3d_028', 'rw', 3, 'Information and Ideas', 'Inferences', 'At an ancient village site, the style of pottery changed abruptly around 1500 BCE, switching to a design common in a region 300 kilometers to the south. Yet the village''s houses, tools, and burial practices remained unchanged across the same period. This evidence suggests that ____', null, 'Which choice most logically completes the text?', '["pottery is the most reliable evidence of who lived at a site", "the new pottery was made by the same people who built the earlier houses but in a different century", "the site was abandoned at the same time the new pottery appeared", "the residents adopted the new style, perhaps through trade, rather than being replaced by a new population"]'::jsonb, 3, null, 'Houses, tools, and burials stayed the same, so the same people likely remained and simply took up a new pottery style.', 'published', 'import', now()),
('rwl3d_029', 'rw', 3, 'Information and Ideas', 'Inferences', 'Researchers played recordings to three groups of mustard plants: the vibrations made by caterpillars chewing leaves, the vibrations made by wind, and silence. When the plants were later attacked by real caterpillars, those that had been exposed to the chewing vibrations produced far more defensive chemicals than plants in the other two groups. This finding suggests that ____', null, 'Which choice most logically completes the text?', '["all vibrations cause plants to produce the same amount of defensive chemicals", "plants produce defensive chemicals only in response to wind", "caterpillars avoid plants that have heard recordings", "the plants can distinguish the vibrations of feeding insects from other vibrations and prepare their defenses in response"]'::jsonb, 3, null, 'Only plants that "heard" chewing produced extra defenses, so they seem to recognize that specific vibration.', 'published', 'import', now()),
('rwl3d_030', 'rw', 3, 'Information and Ideas', 'Inferences', 'When a city eliminated bus fares, supporters predicted that many drivers would leave their cars at home. Ridership did rise by 20 percent in the first year. Surveys found, however, that most of the new riders had previously walked or cycled for those trips, and only a small share had previously driven. These results suggest that ____', null, 'Which choice most logically completes the text?', '["walking and cycling increased after the program began", "the city''s buses were too crowded before the program began", "most residents of the city do not own cars", "eliminating fares may do less to reduce car traffic than its supporters had hoped"]'::jsonb, 3, null, 'Ridership rose mainly among former walkers and cyclists, not drivers, so traffic may not drop much.', 'published', 'import', now()),
('rwl3d_031', 'rw', 3, 'Information and Ideas', 'Inferences', 'A layer of volcanic ash in a Greenland ice core has the same chemical signature as ash from a well-documented eruption of an Icelandic volcano. But the layer is dated about forty years earlier than the recorded eruption. Researchers have checked the ice core''s dating against several independent methods and found it reliable. They therefore conclude that ____', null, 'Which choice most logically completes the text?', '["the volcano erupted only once in its history", "volcanic ash cannot be preserved in ice", "the chemistry of volcanic ash changes after it lands on ice", "an earlier, unrecorded eruption of the same volcano produced the ash"]'::jsonb, 3, null, 'If the dating is accurate, the matching ash must come from a different, earlier eruption of the same volcano.', 'published', 'import', now()),
('rwl3d_032', 'rw', 3, 'Information and Ideas', 'Inferences', 'A common explanation for a zebra''s stripes is camouflage. However, researchers who modeled how lions see found that, at the distances where lions usually detect prey, a zebra''s stripes blur together and the animal is about as visible as a horse with a plain coat. This finding suggests that ____', null, 'Which choice most logically completes the text?', '["the stripes may serve some purpose other than blending into the surroundings", "flies are attracted to striped surfaces", "the stripes help zebras hide from lions in tall grass", "zebras are the only animals with stripes"]'::jsonb, 0, null, 'If striped and plain coats are equally visible to lions, camouflage is unlikely to be the reason for the stripes.', 'published', 'import', now()),
('rwl3d_033', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Oceanographer Sylvia Earle, who has led more than one hundred research ____ spent more than seven thousand hours underwater.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["expeditions, has", "expeditions; has", "expeditions has", "expeditions—has"]'::jsonb, 0, null, 'The clause "who has led more than one hundred research expeditions" starts with a comma, so a comma must close it before the verb "has."', 'published', 'import', now()),
('rwl3d_034', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The bridge''s original steel cables had corroded ____ engineers replaced them one at a time while traffic continued to flow.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["badly consequently,", "badly, consequently,", "badly; consequently,", "badly, consequently"]'::jsonb, 2, null, 'Two independent clauses joined by "consequently" need a semicolon before it and a comma after it.', 'published', 'import', now()),
('rwl3d_035', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The results surprised the research team for one ____ control group improved more than the group that received the new treatment.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["reason: the", "reason the", "reason, the", "reason, being the"]'::jsonb, 0, null, 'A colon introduces the explanation of the "one reason." A comma alone would create a comma splice.', 'published', 'import', now()),
('rwl3d_036', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The city''s oldest building—a stone grain mill constructed in ____ now houses a small museum of local history.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1791,", "1791;", "1791", "1791—"]'::jsonb, 3, null, 'The interruption begins with a dash, so it must end with a dash.', 'published', 'import', now()),
('rwl3d_037', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The ____ arrived before dawn were assigned to the eastern trail; the rest worked near the visitor center.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["volunteers, who", "volunteers who,", "volunteers; who", "volunteers who"]'::jsonb, 3, null, '"who arrived before dawn" identifies which volunteers are meant, so it is essential and takes no commas.', 'published', 'import', now()),
('rwl3d_038', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The tour stops in three cities: Lagos, ____ Accra, Ghana; and Dakar, Senegal.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Nigeria;", "Nigeria", "Nigeria,", "Nigeria:"]'::jsonb, 0, null, 'Items in a list that already contain commas are separated with semicolons.', 'published', 'import', now()),
('rwl3d_039', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'The collection of letters written by the explorer''s crew members during the long Arctic winters ____ now on display at the maritime museum.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have been", "are", "is", "were"]'::jsonb, 2, null, 'The subject is the singular "collection," not "letters" or "members," so the verb is "is."', 'published', 'import', now()),
('rwl3d_040', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Each of the competing robotics teams submitted ____ final design to the judges by the Friday deadline.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["its", "their", "they''re", "it''s"]'::jsonb, 0, null, '"Each" is singular, and the pronoun refers to one team, so the singular possessive "its" is correct.', 'published', 'import', now()),
('rwl3d_041', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'By the time the telescope''s mirror arrived from the factory, the engineers ____ its support structure for nearly a year.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["build", "are building", "will have built", "had been building"]'::jsonb, 3, null, 'The building went on before another past event (the mirror''s arrival), so the past perfect progressive is needed.', 'published', 'import', now()),
('rwl3d_042', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Having analyzed hundreds of soil samples, ____', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the researchers concluded that the field had been farmed for centuries.", "the field was found to have been farmed for centuries.", "the conclusion was that the field had been farmed for centuries.", "centuries of farming were revealed by the researchers'' data."]'::jsonb, 0, null, 'The opening phrase describes who analyzed the samples, so it must be followed directly by "the researchers."', 'published', 'import', now()),
('rwl3d_043', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'The two ____ findings contradicted each other, so the journal asked a third lab to repeat the experiment.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["laboratorie''s", "laboratories''", "laboratories", "laboratory''s"]'::jsonb, 1, null, 'The findings belong to two laboratories, so the plural possessive "laboratories''" is needed.', 'published', 'import', now()),
('rwl3d_044', 'rw', 3, 'Expression of Ideas', 'Transitions', 'Most long-period comets are thought to originate in the Oort cloud, a distant shell of icy objects surrounding the solar system. ____ short-period comets, which return every few decades, probably come from the much closer Kuiper belt.', null, 'Which choice completes the text with the most logical transition?', '["For instance,", "By contrast,", "Likewise,", "Therefore,"]'::jsonb, 1, null, 'The second sentence gives a different origin for a different kind of comet.', 'published', 'import', now()),
('rwl3d_045', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The architect''s design for the new library was widely praised for its beauty. ____ some critics argued that its walls of glass would make the building expensive to heat in winter and to cool in summer.', null, 'Which choice completes the text with the most logical transition?', '["Specifically,", "Thus,", "Indeed,", "Still,"]'::jsonb, 3, null, 'The criticism stands against the praise, so a concession-style contrast fits.', 'published', 'import', now()),
('rwl3d_046', 'rw', 3, 'Expression of Ideas', 'Transitions', 'Glass frogs have nearly transparent skin on their undersides. ____ an observer looking at one from below can see its heart beating.', null, 'Which choice completes the text with the most logical transition?', '["Thus,", "Previously,", "Instead,", "Nonetheless,"]'::jsonb, 0, null, 'Seeing the heart is a result of the transparent skin.', 'published', 'import', now()),
('rwl3d_047', 'rw', 3, 'Expression of Ideas', 'Transitions', 'Popular accounts often credit a single inventor with the creation of the light bulb. ____ the device was the product of decades of work by many people, several of whom developed working bulbs before the most famous version appeared.', null, 'Which choice completes the text with the most logical transition?', '["Similarly,", "In addition,", "For this reason,", "In reality,"]'::jsonb, 3, null, 'The second sentence corrects the popular idea in the first.', 'published', 'import', now()),
('rwl3d_048', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The researchers first tested the new paint in a laboratory under controlled light and humidity. ____ they will expose painted panels to real weather on rooftops in three different cities.', null, 'Which choice completes the text with the most logical transition?', '["Conversely,", "In sum,", "Next,", "Regardless,"]'::jsonb, 2, null, 'The rooftop tests are the following step after the lab tests.', 'published', 'import', now()),
('rwl3d_049', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Great Green Wall is an African-led project launched in 2007.
• It aims to restore damaged land across the Sahel, south of the Sahara.
• The planned belt stretches about 8,000 kilometers from Senegal to Djibouti.
• Its goal is to restore 100 million hectares of land by 2030.
• It is intended to slow the spread of the desert.', null, 'The student wants to emphasize the scale of the project. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Great Green Wall aims to slow the spread of the desert.", "The Great Green Wall aims to restore 100 million hectares of land along a belt stretching about 8,000 kilometers across Africa.", "The Great Green Wall was launched in 2007.", "The Great Green Wall is located in the Sahel region."]'::jsonb, 1, null, 'Only this choice uses the size figures to stress the scale.', 'published', 'import', now()),
('rwl3d_050', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Shield volcanoes have broad, gently sloping sides.
• Their runny lava can flow long distances.
• Mauna Loa in Hawaii is a shield volcano.
• Stratovolcanoes are steep and cone-shaped.
• Their thick lava and ash can cause explosive eruptions.
• Mount Fuji in Japan is a stratovolcano.', null, 'The student wants to contrast the shapes of the two kinds of volcanoes. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Both shield volcanoes and stratovolcanoes are formed by erupting lava.", "Mauna Loa in Hawaii is a shield volcano.", "Stratovolcanoes can erupt explosively because of their thick lava.", "Shield volcanoes such as Mauna Loa have broad, gentle slopes, whereas stratovolcanoes such as Mount Fuji are steep and cone-shaped."]'::jsonb, 3, null, 'Only this choice compares the shapes of the two kinds of volcanoes.', 'published', 'import', now()),
('rwl3d_051', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Robins partly rely on hearing to find worms underground.
• Researchers studied robins at 30 city parks.
• They placed speakers playing traffic noise near half of the feeding areas.
• Speakers near the other feeding areas played nothing.
• They counted how many worms robins caught in an hour.
• Robins near traffic noise caught 30 percent fewer worms.', null, 'The student wants to describe the study''s method to an audience unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["At 30 city parks, researchers placed speakers playing traffic noise near some robin feeding areas and silent speakers near others, then counted the worms robins caught in an hour.", "The study took place in city parks.", "Traffic noise may make it harder for robins to find food.", "Robins near traffic noise caught 30 percent fewer worms."]'::jsonb, 0, null, 'Only this choice explains what the researchers actually did.', 'published', 'import', now()),
('rwl3d_052', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Ibn al-Haytham was a scholar who worked in Cairo.
• He wrote the Book of Optics in the early 1000s.
• He argued that vision happens when light enters the eye.
• He tested his ideas about light with controlled experiments.
• Many historians consider this approach an early form of the scientific method.', null, 'The student wants to explain Ibn al-Haytham''s contribution to scientific method. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Ibn al-Haytham argued that we see because light enters the eye.", "Rather than relying only on reasoning, Ibn al-Haytham tested his ideas about light with controlled experiments.", "Ibn al-Haytham wrote the Book of Optics in the early 1000s.", "Ibn al-Haytham lived in Cairo."]'::jsonb, 1, null, 'Only this choice describes how he tested ideas, which is his contribution to method.', 'published', 'import', now()),
('rwl2e_001', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The food truck''s new menu is remarkably ____: it includes dishes from twelve different countries, from Ethiopian stews to Korean pancakes.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["diverse", "bland", "limited", "predictable"]'::jsonb, 0, null, 'A menu with dishes from twelve countries offers a wide variety, so it is diverse.', 'published', 'import', now()),
('rwl2e_002', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The hikers had to ____ their plans when a rockslide blocked the main trail, choosing a longer route around the valley instead.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["revise", "forget", "publish", "celebrate"]'::jsonb, 0, null, 'Changing to a different route means the hikers had to revise their plans.', 'published', 'import', now()),
('rwl2e_003', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Wind turbines ____ the energy of moving air, turning the motion of their blades into electricity.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["waste", "ignore", "harness", "block"]'::jsonb, 2, null, 'Capturing energy and putting it to use is what harness means.', 'published', 'import', now()),
('rwl2e_004', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Unlike his ____ older brother, who rarely said a word at family gatherings, Teo chatted with every aunt, uncle, and cousin in the room.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["talkative", "cheerful", "curious", "reserved"]'::jsonb, 3, null, 'Someone who rarely speaks at gatherings is reserved, which contrasts with Teo chatting with everyone.', 'published', 'import', now()),
('rwl2e_005', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Before the town approved the new bridge, engineers confirmed that the design was sound, able to carry heavy trucks safely for decades.', null, 'As used in the text, what does the word "sound" most nearly mean?', '["calm", "musical", "noisy", "solid and reliable"]'::jsonb, 3, null, 'A design able to hold heavy trucks safely is solid and reliable.', 'published', 'import', now()),
('rwl2e_006', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The study''s results were ____: three separate laboratories repeated the experiment and obtained nearly identical findings.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["mysterious", "unreliable", "consistent", "temporary"]'::jsonb, 2, null, 'Results that three labs reproduced exactly are consistent.', 'published', 'import', now()),
('rwl2e_007', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The volcano had been ____ for centuries, so residents of nearby villages were surprised when it began releasing clouds of steam last spring.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["famous", "active", "dormant", "crowded"]'::jsonb, 2, null, 'A volcano that has been inactive for a long time is dormant, which explains the surprise.', 'published', 'import', now()),
('rwl2e_008', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Based on wind patterns and satellite images, meteorologists ____ that the storm will reach the coast by Thursday afternoon.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["deny", "predict", "regret", "remember"]'::jsonb, 1, null, 'Using data to say what will happen is to predict.', 'published', 'import', now()),
('rwl2e_009', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'In 1889, newspaper reporter Nellie Bly set out to travel around the world faster than the fictional hero of the novel Around the World in Eighty Days. Traveling by steamship and train, and carrying only a single small bag, she returned to New York just 72 days later, setting a world record.', null, 'Which choice best states the main purpose of the text?', '["To compare different ways of traveling in the 1800s", "To describe a journalist''s record-setting journey", "To argue that newspapers should pay for travel", "To explain how ships crossed the ocean"]'::jsonb, 1, null, 'The text tells how Bly traveled around the world in record time.', 'published', 'import', now()),
('rwl2e_010', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Beavers build dams across streams to create deep ponds. The deep water helps protect the beavers from predators. For example, a beaver lodge''s entrance sits underwater, so wolves and coyotes cannot easily follow a beaver inside.', null, 'Which choice best describes the function of the third sentence in the overall structure of the text?', '["It explains how beavers cut down trees", "It gives a specific example of the benefit described in the second sentence", "It introduces a new topic unrelated to the pond", "It disagrees with the claim in the first sentence"]'::jsonb, 1, null, 'The third sentence shows the protection in action: the underwater entrance keeps predators out.', 'published', 'import', now()),
('rwl2e_011', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Many people believe that the color red makes bulls angry. In fact, bulls cannot distinguish red from many other colors. What provokes a bull in the ring is the movement of the cape, not its color; a bull will charge just as readily at a cape that is blue or white.', null, 'Which choice best describes the overall structure of the text?', '["It lists the colors that bulls prefer", "It compares bulls with other farm animals", "It tells a story about a famous bullfighter", "It presents a common belief and then explains why it is mistaken"]'::jsonb, 3, null, 'The text gives the belief that red angers bulls and then explains that motion, not color, provokes them.', 'published', 'import', now()),
('rwl2e_012', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'The following text is from a short story.

After four years away, Jun walked down Main Street and felt as if someone had shrunk it. The hardware store, which had once seemed enormous, now took up only a corner of the block. Even the bell over the bakery door sounded softer than he remembered.', null, 'Which choice best states the main purpose of the text?', '["To explain why the character left home", "To show how a familiar place looks different to a character after a period away", "To argue that small towns are better than cities", "To describe how a town''s streets were built"]'::jsonb, 1, null, 'Jun notices that everything seems smaller and quieter than he remembered.', 'published', 'import', now()),
('rwl2e_013', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Zoo breeding programs have helped save several endangered species. The California condor, for example, survived only because the last wild birds were captured and bred in zoos. A zoo director argues that breeding programs are the best way to protect endangered animals.

Text 2
Breeding animals in zoos can keep a species alive for a time. But animals released into the wild will struggle if the forests, grasslands, or wetlands they need have been destroyed. Protecting habitat is just as important as breeding.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By claiming that the California condor is no longer endangered anywhere", "By agreeing that breeding programs help but arguing that they are not enough unless wild habitats are also protected", "By arguing that zoos should stop breeding animals", "By agreeing that zoos alone can save endangered species"]'::jsonb, 1, null, 'Text 2 accepts that breeding helps but says released animals need safe habitat.', 'published', 'import', now()),
('rwl2e_014', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
In 2006, astronomers adopted a definition of a planet that requires an object to have cleared other objects from its orbit. Because Pluto shares its region of space with many icy bodies, it was reclassified as a dwarf planet.

Text 2
Some planetary scientists object to that definition. They argue that whether something is a planet should depend on its own features—for example, whether it is massive enough for its gravity to pull it into a round shape—rather than on what else happens to be nearby.', null, 'Based on the texts, how would the scientists in Text 2 most likely respond to the definition described in Text 1?', '["By claiming that Pluto is not round", "By agreeing that Pluto has cleared its orbit", "By arguing that it focuses on an object''s surroundings rather than on the object itself", "By arguing that only Earth should be considered a planet"]'::jsonb, 2, null, 'Text 2''s scientists want a definition based on the object''s own features, like its shape, not on what shares its orbit.', 'published', 'import', now()),
('rwl2e_015', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
E-books are lighter, cheaper, and easier to search than printed books. For these reasons, a school board member argues that the district should replace printed textbooks with e-books.

Text 2
Several studies have found that readers recall the order of events and the details of a long text slightly better when they read it in print than when they read it on a screen. Researchers think the physical feel of turning pages may help readers keep track of where information appears.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By arguing that e-books are too expensive", "By claiming that students read only for entertainment", "By suggesting that convenience is not the only factor to consider, since print may help readers remember more", "By agreeing that print books should no longer be sold"]'::jsonb, 2, null, 'Text 2 points to a memory advantage for print that Text 1 doesn''t consider.', 'published', 'import', now()),
('rwl2e_016', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'In 1976, the voyaging canoe Hōkūleʻa sailed about 2,500 miles from Hawaii to Tahiti without a compass or any modern instruments. Its navigator, Mau Piailug, guided the crew using the positions of the stars, the patterns of ocean swells, and the flight of seabirds. The voyage showed that ancient Polynesians could have settled distant islands on purpose, using careful navigation.', null, 'Which choice best states the main idea of the text?', '["Hawaii and Tahiti were once connected by land", "The canoe was built using modern materials", "The voyage took more than a year to complete", "The voyage showed that traditional Polynesian navigation methods could guide a canoe across thousands of miles of ocean"]'::jsonb, 3, null, 'The text describes a navigator crossing the ocean using only stars, swells, and birds.', 'published', 'import', now()),
('rwl2e_017', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Much of Venice, Italy, rests on millions of wooden piles—tree trunks driven deep into the mud of its lagoon more than a thousand years ago. Wood normally rots, but these piles are completely surrounded by water and mud. Without oxygen, the organisms that cause decay cannot survive, so many of the piles remain strong today.', null, 'According to the text, why have the wooden piles beneath Venice lasted for centuries?', '["They were made from a kind of wood that never decays in air", "They are surrounded by water and mud, where there is too little oxygen for wood to rot", "They are coated with a special paint every year", "They are replaced whenever a building is renovated"]'::jsonb, 1, null, 'The text says the wood sits underwater in mud, where the lack of oxygen keeps it from rotting.', 'published', 'import', now()),
('rwl2e_018', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'The following text is from a short story.

Abby''s heart pounded as she stepped up to the starting line. She glanced at the runners on either side of her, all of them taller. Then she bent down, tightened her laces one more time, and fixed her eyes on the finish line.', null, 'Based on the text, how does Abby feel about the race?', '["She is angry at her coach", "She is bored and wants to go home", "She is nervous but determined to do her best", "She is certain she will win easily"]'::jsonb, 2, null, 'Her pounding heart shows nerves; tightening her laces and focusing on the finish shows determination.', 'published', 'import', now()),
('rwl2e_019', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'To test whether crows can recognize people, researchers wore a particular rubber mask while briefly trapping and banding several birds. For years afterward, crows scolded and dove at anyone wearing that mask, even when the person was simply walking by. People wearing a different mask were mostly ignored.', null, 'Which choice best states the main idea of the text?', '["Crows are frightened of all people", "Crows can recognize individual human faces and remember people who have threatened them", "Crows live longer than most other birds", "Researchers should always wear masks"]'::jsonb, 1, null, 'The study shows that crows remembered and scolded the specific mask linked to a threat.', 'published', 'import', now()),
('rwl2e_020', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Wood frogs, which live as far north as Alaska, survive winter in a surprising way: they freeze. Their hearts stop and up to two-thirds of the water in their bodies turns to ice. Before freezing, the frogs flood their cells with sugar, which keeps the cells from being damaged. In spring, they thaw and hop away.', null, 'According to the text, how do wood frogs survive the winter?', '["They let much of their bodies freeze while sugar protects their cells", "They dig deep burrows below the frost line", "They migrate south before the first frost", "They stay active under the ice all winter"]'::jsonb, 0, null, 'The text explains that the frogs freeze and that sugar in their cells keeps them from being damaged.', 'published', 'import', now()),
('rwl2e_021', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A student claims that the share of commuters in a city who traveled by bike more than doubled between 2014 and 2024.', '{"h": ["Way of commuting", "2014 (%)", "2024 (%)"], "r": [["Car", "72", "61"], ["Bus", "15", "18"], ["Bike", "4", "9"], ["Walk", "9", "12"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the student''s claim?', '["In 2024, 18 percent of commuters took the bus", "Walking was more common than biking in both years", "The share of commuters who drove fell from 72 percent to 61 percent", "The share of commuters who biked rose from 4 percent in 2014 to 9 percent in 2024"]'::jsonb, 3, null, 'The claim is about biking more than doubling; 4 to 9 percent shows that.', 'published', 'import', now()),
('rwl2e_022', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'In a short story, the character Dev is described as persistent.', null, 'Which quotation from the story most effectively illustrates the claim?', '["\"The coach blew her whistle to end practice.\"", "\"Even after the others went home, Dev stayed in the gym, shooting free throw after free throw until he made ten in a row.\"", "\"Dev''s team practiced in the old gym on Tuesday nights.\"", "\"Dev wore the same red sneakers to every game.\""]'::jsonb, 1, null, 'Staying late until he makes ten in a row shows persistence.', 'published', 'import', now()),
('rwl2e_023', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A teacher hypothesizes that students remember more when they spread their studying over several short sessions instead of studying for the same total time all at once.', null, 'Which finding, if true, would most directly support the teacher''s hypothesis?', '["Students who reviewed the material in short sessions spread over a week scored higher on the test than students who studied the same amount in one long session", "Most students prefer to study in the evening", "Students who studied with a partner talked more during class", "Students reported that long study sessions were tiring"]'::jsonb, 0, null, 'Only this finding compares spread-out study with one long session and shows better results.', 'published', 'import', now()),
('rwl2e_024', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A librarian notes that visits to the town library rose sharply during the summer reading program and fell once school began. The table shows that ____', '{"h": ["Month", "Library visits"], "r": [["May", "3,100"], ["June", "4,200"], ["July", "5,400"], ["August", "4,900"], ["September", "3,300"]]}'::jsonb, 'Which choice most effectively uses data from the table to complete the statement?', '["visits in May and September were similar", "the library was open five months", "visits rose from 3,100 in May to 5,400 in July before dropping to 3,300 in September", "more people visited in June than in May"]'::jsonb, 2, null, 'Only this choice shows the summer peak and the fall drop that the statement describes.', 'published', 'import', now()),
('rwl2e_025', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A store manager claims that a new advertising campaign caused a 30 percent increase in sunscreen sales at the store this summer.', null, 'Which finding, if true, would most directly weaken the claim?', '["The advertisements appeared on buses and at the beach", "The store sells several brands of sunscreen", "Sunscreen sales rose most during July", "Sales of sunscreen rose by the same amount in nearby towns where no advertisements were shown"]'::jsonb, 3, null, 'If sales rose just as much without the ads, the ads probably did not cause the increase.', 'published', 'import', now()),
('rwl2e_026', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'In a poem, the speaker describes how ordinary objects in her hometown bring back memories of her childhood.', null, 'Which quotation from the poem most effectively illustrates the claim?', '["\"The maple I climbed as a child / still holds the shape of my hands.\"", "\"Rain is forecast for Tuesday.\"", "\"The bus pulls in at seven, / and the doors fold open.\"", "\"The store sells bread, milk, and string.\""]'::jsonb, 0, null, 'This quotation links a present object to the speaker''s childhood memory.', 'published', 'import', now()),
('rwl2e_027', 'rw', 2, 'Information and Ideas', 'Inferences', 'At a site in Wyoming, archaeologists found thousands of bison bones, many with thin cuts made by stone blades. Stone tools of the same kind were found buried among the bones. The archaeologists concluded that ____', null, 'Which choice most logically completes the text?', '["the people at the site did not eat meat", "the tool marks were made by people living at the site", "the site was flooded every spring", "the bones belonged to animals that died of old age"]'::jsonb, 1, null, 'Cut marks made by stone tools on the bones point to people butchering animals there.', 'published', 'import', now()),
('rwl2e_028', 'rw', 2, 'Information and Ideas', 'Inferences', 'Researchers measured water temperature and counted trout along a stream. Where trees lined the banks, the water stayed below 18°C and trout were common. Where the stream ran through open fields, the water often rose above 22°C and few trout were found. These results suggest that ____', null, 'Which choice most logically completes the text?', '["trout prefer warm water", "the trees were planted to attract birds", "the shade from the trees may help keep the stream cool enough for trout", "streams in open fields always have more fish"]'::jsonb, 2, null, 'Trout were found where trees shaded the cool water, but not in the sunny, warmer stretch.', 'published', 'import', now()),
('rwl2e_029', 'rw', 2, 'Information and Ideas', 'Inferences', 'Some local officials blamed a hospital''s recent expansion for the region''s shortage of nurses. However, records show that the number of unfilled nursing jobs in the region had been rising steadily for two years before the expansion was even announced. This suggests that ____', null, 'Which choice most logically completes the text?', '["the hospital expansion caused the nurse shortage", "the shortage of nurses had already begun before the hospital expanded", "the hospital hired too many nurses after expanding", "nurses preferred working in smaller hospitals"]'::jsonb, 1, null, 'Job openings were already rising for two years before the expansion, so the shortage started earlier.', 'published', 'import', now()),
('rwl2e_030', 'rw', 2, 'Information and Ideas', 'Inferences', 'Two unsigned landscape paintings were found in an attic. Tests showed that both contain a yellow paint that manufacturers stopped selling around 1850 and that none contain any of the new paints that became common after that date. Based on this evidence, experts suggest that ____', null, 'Which choice most logically completes the text?', '["the paintings were stored in a museum", "the paintings were probably made before 1850", "the paintings were made after 1900", "the artist painted only landscapes"]'::jsonb, 1, null, 'The paintings use a yellow paint that stopped being sold around 1850, so they likely date from before then.', 'published', 'import', now()),
('rwl2e_031', 'rw', 2, 'Information and Ideas', 'Inferences', 'In a planetarium, researchers projected a night sky over young songbirds that were preparing to migrate. When the projected stars were rotated, the birds turned to face a different direction, matching the change in the star pattern. This result suggests that ____', null, 'Which choice most logically completes the text?', '["the birds can migrate only in cloudy weather", "the birds do not migrate at all", "the birds may be using the stars to find their way", "the birds were frightened by the planetarium"]'::jsonb, 2, null, 'The birds changed direction when the projected stars were moved, so the stars seem to guide them.', 'published', 'import', now()),
('rwl2e_032', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The lighthouse was built in 1852 to guide ships into the ____ then, it has been rebuilt twice after powerful storms.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["harbor, since", "harbor, and since", "harbor since", "harbor. Since"]'::jsonb, 3, null, 'The text contains two complete sentences, so a period separates them.', 'published', 'import', now()),
('rwl2e_033', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The science fair included three winning ____ a solar-powered fan, a water filter made from sand, and a model of a wind farm.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["projects:", "projects, and", "projects", "projects;"]'::jsonb, 0, null, 'A colon after a complete sentence introduces the list that follows.', 'published', 'import', now()),
('rwl2e_034', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Maya ____ renowned architect and artist, designed the Vietnam Veterans Memorial while she was still a college student.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Lin. A", "Lin; a", "Lin, a", "Lin a"]'::jsonb, 2, null, '"a renowned architect" describes Maya Lin and is set off with commas.', 'published', 'import', now()),
('rwl2e_035', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The forecast called for heavy ____ only a light dusting fell overnight.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["snow; however", "snow; however,", "snow however", "snow, however,"]'::jsonb, 1, null, '"However" joins two complete sentences here, so a semicolon goes before it and a comma after it.', 'published', 'import', now()),
('rwl2e_036', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The dry, rocky land of Death ____ receives only about two inches of rain in a typical year.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Valley;", "Valley,", "Valley", "Valley:"]'::jsonb, 2, null, 'The subject "the dry, rocky land of Death Valley" shouldn''t be separated from its verb "receives."', 'published', 'import', now()),
('rwl2e_037', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The list of volunteers for the beach cleanup ____ grown to more than two hundred names.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are", "were", "have", "has"]'::jsonb, 3, null, 'The subject is "the list," which is singular.', 'published', 'import', now()),
('rwl2e_038', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'After the championship game, the players thanked ____ coach for a season of hard work.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["their", "its", "our", "his or her"]'::jsonb, 0, null, '"The players" is plural, so the plural pronoun "their" is correct.', 'published', 'import', now()),
('rwl2e_039', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'In 1955, Rosa Parks refused to give up her seat on a bus in Montgomery, Alabama, and her arrest soon ____ a citywide bus boycott.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["began", "begins", "is beginning", "will begin"]'::jsonb, 0, null, 'The sentence describes an event in 1955, so the past tense is needed.', 'published', 'import', now()),
('rwl2e_040', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Returning to their camp in the morning, ____', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the scientists noticed that the ice had cracked.", "a crack in the ice had formed overnight.", "the ice was noticed to have cracked.", "the crack in the ice was noticed by them."]'::jsonb, 0, null, 'The opening phrase describes who returned to camp, so it must be followed by "the scientists."', 'published', 'import', now()),
('rwl2e_041', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The library opened a new ____ section filled with picture books and comfortable chairs.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["childrens''", "children", "childrens", "children''s"]'::jsonb, 3, null, '"Children" is already plural, so its possessive is "children''s."', 'published', 'import', now()),
('rwl2e_042', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Many animals use camouflage to hide from predators. ____ the arctic hare''s white winter coat makes it nearly invisible against the snow.', null, 'Which choice completes the text with the most logical transition?', '["However,", "For example,", "Finally,", "In contrast,"]'::jsonb, 1, null, 'The second sentence gives an example of an animal using camouflage.', 'published', 'import', now()),
('rwl2e_043', 'rw', 2, 'Expression of Ideas', 'Transitions', 'The post office installed new automated conveyor belts last year. ____ it now sorts nearly twice as many packages each hour.', null, 'Which choice completes the text with the most logical transition?', '["As a result,", "Similarly,", "For instance,", "Even so,"]'::jsonb, 0, null, 'Faster processing is a result of the new conveyor belts.', 'published', 'import', now()),
('rwl2e_044', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Many people expect deserts to be hot all the time. ____ temperatures in some deserts can fall below freezing at night.', null, 'Which choice completes the text with the most logical transition?', '["Therefore,", "Likewise,", "Additionally,", "However,"]'::jsonb, 3, null, 'The second sentence contrasts with the expectation in the first.', 'published', 'import', now()),
('rwl2e_045', 'rw', 2, 'Expression of Ideas', 'Transitions', 'The band set up its instruments on the stage. ____ the crowd outside grew larger as people waited for the doors to open.', null, 'Which choice completes the text with the most logical transition?', '["In conclusion,", "For example,", "As a result,", "Meanwhile,"]'::jsonb, 3, null, 'The two actions happen at the same time.', 'published', 'import', now()),
('rwl2e_046', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Planting cover crops in winter keeps soil from washing away. ____ the plants add nutrients to the soil when they are later plowed under.', null, 'Which choice completes the text with the most logical transition?', '["Moreover,", "Nevertheless,", "Instead,", "In contrast,"]'::jsonb, 0, null, 'The second sentence adds another benefit of the cover crops.', 'published', 'import', now()),
('rwl2e_047', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Panama Canal opened in 1914.
• It is about 50 miles long.
• It connects the Atlantic and Pacific Oceans.
• Before it opened, ships had to sail around the southern tip of South America.
• The canal shortened a trip from New York to San Francisco by about 8,000 miles.', null, 'The student wants to explain why the Panama Canal was important for shipping. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Panama Canal let ships travel between the Atlantic and Pacific without sailing around South America, saving about 8,000 miles.", "The Panama Canal uses locks to raise and lower ships.", "The Panama Canal opened in 1914.", "The Panama Canal is about 50 miles long."]'::jsonb, 0, null, 'Only this choice explains the shortcut that made the canal important.', 'published', 'import', now()),
('rwl2e_048', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• African bush elephants live in Africa.
• They can weigh about 6 tons.
• Asian elephants live in forests of South and Southeast Asia.
• They weigh about 4 tons.
• Both kinds use their trunks to drink and to gather food.', null, 'The student wants to compare the sizes of the two animals. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Asian elephants live in forests of South and Southeast Asia.", "African bush elephants live in Africa.", "The African bush elephant can weigh about 6 tons, while the much smaller Asian elephant weighs about 4 tons.", "Both kinds of elephants use their trunks to drink."]'::jsonb, 2, null, 'Only this choice compares the animals'' sizes.', 'published', 'import', now()),
('rwl2e_049', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Mary Golda Ross was born in Oklahoma in 1908.
• She was a member of the Cherokee Nation.
• She is considered the first known Native American woman engineer.
• She worked on early spacecraft designs at an aerospace company.
• In 2019, she appeared on a U.S. one-dollar coin.', null, 'The student wants to introduce Mary Golda Ross to an audience unfamiliar with her. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["She worked on early spacecraft designs.", "She was born in Oklahoma in 1908.", "In 2019, she appeared on a one-dollar coin.", "Mary Golda Ross, a member of the Cherokee Nation, is considered the first known Native American woman engineer and helped design early spacecraft."]'::jsonb, 3, null, 'Only this choice names her and explains who she is and why she matters.', 'published', 'import', now()),
('rwl2e_050', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The steelpan was developed in Trinidad and Tobago.
• It was first made in the 1930s and 1940s from oil drums.
• Each instrument has dented sections hammered into the metal.
• Each section is tuned to a different note.
• A player strikes the sections with rubber-tipped sticks to make sound.
• Steelpan bands often play at Carnival.', null, 'The student wants to explain how the instrument makes sound. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The steelpan makes sound when a player strikes dented sections of a metal drum, each tuned to a different note.", "The steelpan was first made in the 1930s and 1940s.", "Steelpan bands often play at Carnival.", "The steelpan was developed in Trinidad and Tobago."]'::jsonb, 0, null, 'Only this choice describes how the steelpan produces sound.', 'published', 'import', now())
on conflict (id) do nothing;
